contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0, "amount must be positive");
        require(amount <= address(this).balance, "not enough test balance");

        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;

        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        uint beforeUserBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        c.Collect(amount * 2); bool __rev0 = __ESBMC_reverted(); if (__rev0) { } else { }

        bool reverted = (c.balances(address(this)) == beforeUserBalance) &&
                        (address(c).balance == beforeContractBalance) &&
                        (address(this).balance == beforeThisBalance);

        assert(reverted);
    }

    receive() external payable {}
}

